#!ibl edition=2
$u = "http://127.0.0.1:8979/"
$n = [limbs:browser]{op:"navigate", url:f"${u}login", driver:"playwright", wait:"load"}
$tu = [limbs:browser]{op:"type", selector:"input[name=user]", text:"lsi47_staff"}
